import json
import sys

def validate_function_inputs(input_function_name, input_function_inputs_json, function_json):
    # Initialize variables
    valid = True
    error_reason = ''

    # 1. Load function definitions
    try:
        functions = json.loads(function_json, strict=False)
    except json.JSONDecodeError:
        return False, 'Tool JSON is not valid!\n'

    # 2. Load input parameters
    try:
        if not input_function_inputs_json or input_function_inputs_json.strip() == 'null':
            input_function_inputs = {}
        else:
            input_function_inputs = json.loads(input_function_inputs_json, strict=False)

            if input_function_inputs is None:
                input_function_inputs = {}

    except json.JSONDecodeError:
        return False, 'Input parameters are not valid JSON!\n'

    # 3. Find the function definition
    function_definition = next(
        (func['function'] for func in functions if func['function']['name'] == input_function_name), None)

    if not function_definition:
        return False, f'Function "{input_function_name}" not found. Ensure you are using the correct function name!\n'

    # 4. Get Schema Details
    parameters_schema = function_definition.get('parameters', {})
    required_params = parameters_schema.get('required', [])
    properties = parameters_schema.get('properties', {})

    # 5. Check Required Parameters
    for param in required_params:
        if param not in input_function_inputs:
            valid = False
            error_reason += f'Required parameter "{param}" is missing!\n'

    # 6. Check for Unexpected Parameters
    for param in input_function_inputs:
        if param not in properties:
            valid = False
            error_reason += f'Unexpected parameter "{param}" provided.\n\n' \
                            f'Description for function "{input_function_name}": "{function_definition.get("description", "")}"\n'

    return valid, error_reason

# --- Execution ---

try:
    input_function_name = sys.argv[1]
    input_function_inputs_json = sys.argv[2]
    function_json = sys.argv[3]

    is_valid, reason = validate_function_inputs(input_function_name, input_function_inputs_json, function_json)

    if not is_valid:
        print('Unable to call tool due to validation error!\n' + reason)

except IndexError:
    is_valid = False
    reason = "Error: Missing arguments. Expected [name] [inputs_json] [tools_json]"

import sys
import json
import ast

# 1. Get Input
try:
    raw_input = sys.argv[1].strip()
except IndexError:
    raw_input = ""

normalized_commands = None

# --- Logic Waterfall ---

# Step 1: Try JSON Parsing
# Handles: ["show clock", "show ip"]  -> List
# Handles: "show clock"               -> String
try:
    normalized_commands = json.loads(raw_input)
except json.JSONDecodeError:
    pass

# Step 2: Try Python Literal Evaluation (if Step 1 failed)
# Handles: "show clock", "show ip" (tuple syntax) -> List
# Handles: ['show clock', 'show ip'] (single quotes) -> List
if normalized_commands is None:
    try:
        evaluated = ast.literal_eval(raw_input)
        if isinstance(evaluated, (list, tuple)):
            normalized_commands = list(evaluated)
    except (ValueError, SyntaxError):
        pass

# Step 3: Comma Separation Fallback (if Step 1 & 2 failed)
# Handles: show clock, show ip int brief (raw text list) -> List
if normalized_commands is None:
    if ',' in raw_input:
        # Split by comma and clean up whitespace
        items = [item.strip() for item in raw_input.split(',')]

        # Remove surrounding quotes if user wrapped individual items in them 
        # (e.g. "cmd1", "cmd2" that somehow failed previous checks)
        cleaned_items = []
        for i in items:
            if (i.startswith('"') and i.endswith('"')) or (i.startswith("'") and i.endswith("'")):
                cleaned_items.append(i[1:-1])
            else:
                cleaned_items.append(i)
        normalized_commands = cleaned_items

    else:
        # Step 4: Single Raw String Fallback
        # Handles: show clock (no quotes, no commas) -> String

        # If the input still has surrounding quotes but failed JSON (rare), strip them
        if len(raw_input) >= 2 and (
            (raw_input.startswith('"') and raw_input.endswith('"')) or 
            (raw_input.startswith("'") and raw_input.endswith("'"))
        ):
            normalized_commands = raw_input[1:-1]
        else:
            normalized_commands = raw_input

# --- Output ---
normalized_commands = json.dumps(normalized_commands)
